"""Atomic canonical Free Course authoring, content archival and guarded course deletion."""
from __future__ import annotations

import hashlib
import json
import re
from decimal import Decimal, InvalidOperation
from uuid import uuid4

from django.db import connection, transaction
from django.utils import timezone
from django.utils.http import quote_etag

from . import free_course_authoring as documents
from . import free_course_catalogue
from .free_course_writer_mode import CANONICAL, FreeCourseWriterDisabled, _catalogue_lock, require_mode


MAX_REQUEST_BYTES = 2 * 1024 * 1024
MAX_SETTINGS_BYTES = 256 * 1024
MAX_WEEKS = 100
MAX_COMPONENTS = 500
MAX_COMPONENTS_PER_WEEK = 100
PROGRAMME_MARKER = "FREE-COURSES"
IDEMPOTENCY_OPERATION = "free_course.create.v1"
IDEMPOTENCY_KEY_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:-]{7,254}$")


class MutationError(ValueError):
    def __init__(self, code, message, status=400, **details):
        self.code = code
        self.status = status
        self.details = details
        super().__init__(message)


def _clean(value, *, maximum=None, required=False, label="value"):
    text = str(value or "").strip()
    if required and not text:
        raise MutationError("validation_error", f"{label} is required.")
    if maximum is not None and len(text) > maximum:
        raise MutationError("validation_error", f"{label} is too long.")
    if any(ord(char) < 32 for char in text):
        raise MutationError("validation_error", f"{label} contains invalid characters.")
    return text


def _integer(value, *, minimum=0, maximum=None, label="value"):
    if isinstance(value, bool):
        raise MutationError("validation_error", f"{label} must be an integer.")
    try:
        result = int(value)
    except (TypeError, ValueError):
        raise MutationError("validation_error", f"{label} must be an integer.")
    if result < minimum or (maximum is not None and result > maximum):
        raise MutationError("validation_error", f"{label} is outside the allowed range.")
    return result


def _decimal(value, *, label="value"):
    try:
        result = Decimal(str(value if value not in (None, "") else 0))
    except (InvalidOperation, ValueError):
        raise MutationError("validation_error", f"{label} must be numeric.")
    if not result.is_finite() or result < 0:
        raise MutationError("validation_error", f"{label} must be zero or greater.")
    return result


def _json_object(value, *, label):
    if value is None:
        value = {}
    if not isinstance(value, dict):
        raise MutationError("validation_error", f"{label} must be a JSON object.")
    encoded = documents.canonical_json_bytes(value)
    if len(encoded) > MAX_SETTINGS_BYTES:
        raise MutationError("settings_too_large", f"{label} exceeds 256 KiB.", status=413)
    return value


def _new_id(prefix):
    return f"{prefix}-{uuid4().hex.upper()}"


def _rows(cursor):
    names = [column[0] for column in cursor.description or ()]
    return [dict(zip(names, row)) for row in cursor.fetchall()]


def _course_rows(*, lock=False):
    suffix = " for update" if lock else ""
    with connection.cursor() as cursor:
        cursor.execute(
            "select * from curriculum.free_courses order by display_order, id" + suffix
        )
        return _rows(cursor)


def _tree(course_id, *, lock=False, include_deleted=False):
    suffix = " for update" if lock else ""
    current = "" if include_deleted else " and deleted_at is null"
    with connection.cursor() as cursor:
        cursor.execute(
            "select * from curriculum.free_courses where id=%s" + suffix,
            [course_id],
        )
        course = next(iter(_rows(cursor)), None)
        if not course:
            raise MutationError("free_course_not_found", "Free Course not found.", status=404)
        cursor.execute(
            "select * from curriculum.free_course_weeks where course_id=%s" + current + " order by id" + suffix,
            [course_id],
        )
        weeks = _rows(cursor)
        week_ids = [row["id"] for row in weeks]
        components = []
        if week_ids:
            cursor.execute(
                "select * from curriculum.free_programme_components "
                "where free_module_id = any(%s::varchar[])" + current + " order by id" + suffix,
                [week_ids],
            )
            components = _rows(cursor)
    return course, weeks, components


def _catalogue_revision(rows=None):
    return documents.catalogue_revision(rows if rows is not None else free_course_catalogue.courses())


def _expected(payload, key="expectedRevision"):
    value = _clean(payload.get(key)) if isinstance(payload, dict) else ""
    if not value:
        raise MutationError(
            "precondition_required",
            f"{key} is required. Reload the Free Course and try again.",
            status=428,
        )
    return value


def _check_revision(expected, current, *, scope):
    if expected != current:
        raise MutationError(
            "stale_revision",
            "The Free Course changed after it was opened. Reload before saving.",
            status=409,
            scope=scope,
            expectedRevision=expected,
            currentRevision=current,
        )


def _client_id(value, seen, label):
    result = _clean(value, maximum=128, required=True, label=label)
    if result in seen:
        raise MutationError("duplicate_client_id", f"Duplicate {label}: {result}.")
    seen.add(result)
    return result


def _normalise_component(raw, *, index, existing=None):
    if not isinstance(raw, dict):
        raise MutationError("validation_error", "Each component must be an object.")
    component_type = _clean(raw.get("type"), maximum=64, required=True, label="component type")
    if existing is not None and component_type != str(existing.get("type") or ""):
        raise MutationError("component_type_change_forbidden", "Existing component types cannot be changed.", status=409)
    settings = _json_object(raw.get("settings"), label="component settings")
    if existing is not None:
        previous_settings = existing.get("settings_json") or {}
        if isinstance(previous_settings, str):
            try:
                previous_settings = json.loads(previous_settings)
            except ValueError:
                previous_settings = {}
        previous_quiz = str((previous_settings or {}).get("linkedQuizId") or "").strip()
        requested_quiz = str(settings.get("linkedQuizId") or "").strip()
        if previous_quiz != requested_quiz:
            raise MutationError(
                "linked_quiz_change_forbidden",
                "Use the canonical Free Course quiz controls to link or unlink quizzes.",
                status=409,
            )
    return {
        "type": component_type,
        "title": _clean(raw.get("title"), maximum=255, required=True, label="component title"),
        "description": str(raw.get("description") or ""),
        "expected_otjh": _decimal(raw.get("expectedOtjh"), label="expectedOtjh"),
        "points": _integer(raw.get("points", 0), minimum=0, maximum=1000000, label="points"),
        "reflection_required": bool(raw.get("reflectionRequired")),
        "workplace_evidence_required": bool(raw.get("workplaceEvidenceRequired")),
        "tutor_validation_required": bool(raw.get("tutorValidationRequired")),
        "display_order": _integer(raw.get("displayOrder", index), minimum=0, label="component displayOrder"),
        "settings_json": settings,
    }


def _normalise_week(raw, *, index, existing=None):
    if not isinstance(raw, dict):
        raise MutationError("validation_error", "Each week must be an object.")
    status = _clean(raw.get("status") or (existing or {}).get("status") or "active").lower()
    if status not in {"active", "inactive"}:
        raise MutationError("validation_error", "Week status must be active or inactive.")
    outcomes = raw.get("learningOutcomes", (existing or {}).get("learning_outcomes") or [])
    if not isinstance(outcomes, (list, dict, str)):
        raise MutationError("validation_error", "learningOutcomes has an invalid shape.")
    return {
        "week_number": _integer(raw.get("weekNumber", index + 1), minimum=1, label="weekNumber"),
        "title": _clean(raw.get("title") or raw.get("weekTitle"), maximum=255, required=True, label="week title"),
        "summary": str(raw.get("summary") or raw.get("weekSummary") or ""),
        "learning_outcomes": outcomes,
        "status": status,
        "holiday_note_enabled": bool(raw.get("holidayNoteEnabled")),
        "holiday_note": str(raw.get("holidayNote") or ""),
        "legacy_copied_from_week_id": _clean(raw.get("legacyCopiedFromWeekId"), maximum=128) or None,
        "display_order": _integer(raw.get("displayOrder", index), minimum=0, label="week displayOrder"),
    }


def _course_values(raw):
    if not isinstance(raw, dict):
        raise MutationError("validation_error", "course must be an object.")
    course_type = _clean(raw.get("courseType") or "free").lower()
    if course_type not in {"free", "apprentices"}:
        raise MutationError("validation_error", "Unsupported courseType.")
    is_for_sale = bool(raw.get("isForSale"))
    price = None if not is_for_sale else _decimal(raw.get("price"), label="price")
    if is_for_sale and (price is None or price <= 0 or price > Decimal("99999999.99")):
        raise MutationError("validation_error", "A valid positive price is required.")
    return {
        "course_name": _clean(raw.get("courseName") or raw.get("title"), maximum=255, required=True, label="courseName"),
        "description": str(raw.get("description") or ""),
        "cover_image_url": str(raw.get("coverImageUrl") or ""),
        "course_type": course_type,
        "is_for_sale": is_for_sale,
        "price": price,
        "currency": "GBP",
    }


def _stored_cover(course_id, value):
    """A cover as a storage URL instead of an inline data: URI in the column.

    The picker sends an uploaded file as base64; kept in the column it rode in
    every catalogue and course response and could never be cached by the
    browser. Same helper, path shape and failure behaviour as module covers:
    URLs and '' pass through untouched.
    """
    from .views import CoverImageError, stored_module_cover_image  # lazy: views is heavy, keep this module light to import

    try:
        return stored_module_cover_image(course_id, value)
    except CoverImageError as error:
        raise MutationError("invalid_cover", str(error)) from error


def _validate_shape(weeks):
    if not isinstance(weeks, list):
        raise MutationError("validation_error", "weeks must be a list.")
    if not weeks:
        raise MutationError("validation_error", "A Free Course needs at least one week.")
    if len(weeks) > MAX_WEEKS:
        raise MutationError("limit_exceeded", "A course can contain at most 100 weeks.")
    total = 0
    active_nonempty = False
    week_orders = set()
    for week_index, week in enumerate(weeks):
        if not isinstance(week, dict):
            raise MutationError("validation_error", "Each week must be an object.")
        components = week.get("components", []) if isinstance(week, dict) else []
        if not isinstance(components, list):
            raise MutationError("validation_error", "components must be a list.")
        if len(components) > MAX_COMPONENTS_PER_WEEK:
            raise MutationError("limit_exceeded", "A week can contain at most 100 components.")
        week_order = _integer(week.get("displayOrder", week_index), minimum=0, label="week displayOrder")
        if week_order in week_orders:
            raise MutationError("duplicate_display_order", "Week displayOrder values must be unique.")
        week_orders.add(week_order)
        component_orders = set()
        for component_index, component in enumerate(components):
            if not isinstance(component, dict):
                raise MutationError("validation_error", "Each component must be an object.")
            component_order = _integer(component.get("displayOrder", component_index), minimum=0, label="component displayOrder")
            if component_order in component_orders:
                raise MutationError("duplicate_display_order", "Component displayOrder values must be unique within a week.")
            component_orders.add(component_order)
        total += len(components)
        status = _clean(week.get("status") or "active").lower()
        if status == "active" and not components:
            raise MutationError("active_week_empty", "Active weeks must contain at least one component.")
        active_nonempty = active_nonempty or (status == "active" and bool(components))
    if total > MAX_COMPONENTS:
        raise MutationError("limit_exceeded", "A course can contain at most 500 components.")
    if not active_nonempty:
        raise MutationError("validation_error", "A course needs at least one active, non-empty week.")


def request_digest(payload):
    return hashlib.sha256(documents.canonical_json_bytes({
        "operation": IDEMPOTENCY_OPERATION,
        "payload": payload,
    })).hexdigest()


def validate_idempotency_key(value):
    value = str(value or "").strip()
    if not IDEMPOTENCY_KEY_RE.fullmatch(value):
        raise MutationError(
            "invalid_idempotency_key",
            "Idempotency-Key must be 8-255 characters using letters, numbers, . _ : or -.",
        )
    return value


def _ledger_row(staff_id, key, *, lock=False):
    suffix = " for update" if lock else ""
    with connection.cursor() as cursor:
        cursor.execute(
            "select * from curriculum.free_course_authoring_idempotency "
            "where staff_subject_id=%s and operation=%s and idempotency_key=%s" + suffix,
            [staff_id, IDEMPOTENCY_OPERATION, key],
        )
        return next(iter(_rows(cursor)), None)


def _purge_expired_idempotency():
    """Bound lazy retention cleanup to avoid an unbounded delete on a request."""
    with connection.cursor() as cursor:
        cursor.execute(
            "with expired as (select id from curriculum.free_course_authoring_idempotency "
            "where state='completed' and expires_at < transaction_timestamp() order by expires_at,id limit 500) "
            "delete from curriculum.free_course_authoring_idempotency l using expired e where l.id=e.id"
        )


def _replay(row, digest):
    if row["request_sha256"] != digest:
        raise MutationError("idempotency_key_reused", "This Idempotency-Key was used for a different request.", status=409)
    if row["state"] != "completed":
        raise MutationError("idempotency_in_progress", "The create request is still in progress.", status=409)
    return {
        "replayed": True,
        "status": row["response_status"],
        "body": row["response_body"],
        "etag": row["response_etag"],
        "location": row["response_location"],
    }


def create_course(payload, *, staff_id, idempotency_key):
    if not isinstance(payload, dict):
        raise MutationError("validation_error", "Request body must be an object.")
    expected = _expected(payload)
    key = validate_idempotency_key(idempotency_key)
    digest = request_digest(payload)
    raw_weeks = payload.get("weeks")
    _validate_shape(raw_weeks)

    require_mode(CANONICAL)
    with transaction.atomic():
        _purge_expired_idempotency()
        existing_ledger = _ledger_row(staff_id, key, lock=True)
        if existing_ledger:
            return _replay(existing_ledger, digest)
        require_mode(CANONICAL)
        with connection.cursor() as cursor:
            cursor.execute(
                "insert into curriculum.free_course_authoring_idempotency "
                "(staff_subject_id,operation,idempotency_key,request_sha256) "
                "values (%s,%s,%s,%s) on conflict do nothing returning id",
                [staff_id, IDEMPOTENCY_OPERATION, key, digest],
            )
            claimed = cursor.fetchone()
        if not claimed:
            return _replay(_ledger_row(staff_id, key, lock=True), digest)

        _catalogue_lock()
        require_mode(CANONICAL)
        courses = _course_rows(lock=True)
        _check_revision(expected, _catalogue_revision(courses), scope="catalogue")

        course_id = _new_id("FREECOURSE")
        course = _course_values(payload.get("course"))
        course["cover_image_url"] = _stored_cover(course_id, course["cover_image_url"])
        client_map = {"courses": {}, "weeks": {}, "components": {}}
        seen_clients = set()
        course_client = _client_id(payload.get("clientId"), seen_clients, "course clientId")
        client_map["courses"][course_client] = course_id
        now = timezone.now()
        with connection.cursor() as cursor:
            cursor.execute(
                "insert into curriculum.free_courses "
                "(id,course_name,description,cover_image_url,display_order,week_count,component_count,total_otjh,created_at,updated_at,course_type,is_for_sale,price,currency) "
                "values (%s,%s,%s,%s,%s,0,0,0,%s,%s,%s,%s,%s,%s)",
                [course_id, course["course_name"], course["description"], course["cover_image_url"],
                 max((row.get("display_order") or 0 for row in courses), default=-1) + 1,
                 now, now, course["course_type"], course["is_for_sale"], course["price"], course["currency"]],
            )
            component_count = 0
            total_otjh = Decimal("0")
            for week_index, raw_week in enumerate(raw_weeks):
                week = _normalise_week(raw_week, index=week_index)
                week_client = _client_id(raw_week.get("clientId"), seen_clients, "week clientId")
                week_id = _new_id("FREEWEEK")
                client_map["weeks"][week_client] = week_id
                components = raw_week.get("components", [])
                week_total = sum((_decimal(item.get("expectedOtjh"), label="expectedOtjh") for item in components), Decimal("0"))
                cursor.execute(
                    "insert into curriculum.free_course_weeks "
                    "(id,course_id,display_order,component_count,total_otjh,created_at,updated_at,week_number,title,summary,learning_outcomes,status,holiday_note_enabled,holiday_note,legacy_copied_from_week_id) "
                    "values (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb,%s,%s,%s,%s)",
                    [week_id, course_id, week["display_order"], len(components), week_total, now, now,
                     week["week_number"], week["title"], week["summary"], json.dumps(week["learning_outcomes"]),
                     week["status"], week["holiday_note_enabled"], week["holiday_note"], week["legacy_copied_from_week_id"]],
                )
                for component_index, raw_component in enumerate(components):
                    values = _normalise_component(raw_component, index=component_index)
                    component_client = _client_id(raw_component.get("clientId"), seen_clients, "component clientId")
                    component_id = _new_id("FREECOMP")
                    client_map["components"][component_client] = component_id
                    cursor.execute(
                        "insert into curriculum.free_programme_components "
                        "(id,free_module_id,programme_id,type,title,description,expected_otjh,points,reflection_required,workplace_evidence_required,tutor_validation_required,display_order,settings_json,created_at,updated_at) "
                        "values (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb,%s,%s)",
                        [component_id, week_id, PROGRAMME_MARKER, values["type"], values["title"], values["description"],
                         values["expected_otjh"], values["points"], values["reflection_required"],
                         values["workplace_evidence_required"], values["tutor_validation_required"],
                         values["display_order"], json.dumps(values["settings_json"]), now, now],
                    )
                component_count += len(components)
                total_otjh += week_total
            cursor.execute(
                "update curriculum.free_courses set week_count=%s,component_count=%s,total_otjh=%s,updated_at=%s where id=%s",
                [len(raw_weeks), component_count, total_otjh, now, course_id],
            )

        document = documents.course_document(course_id, read_snapshot=False)
        document["clientIdMap"] = client_map
        from .free_course_videos import queue_saved_videos
        queue_saved_videos(course_id, [], document)
        etag = quote_etag(document["revision"])
        location = f"/curriculum_api/curriculum/free-courses/{course_id}/authoring/"
        with connection.cursor() as cursor:
            cursor.execute(
                "update curriculum.free_course_authoring_idempotency set "
                "state='completed',course_id=%s,response_status=201,response_body=%s::jsonb,"
                "response_etag=%s,response_location=%s,completed_at=transaction_timestamp() "
                "where id=%s",
                [course_id, json.dumps(document), etag, location, claimed[0]],
            )
        return {"replayed": False, "status": 201, "body": document, "etag": etag, "location": location}


def _dependency_counts(course_id, week_ids, component_ids):
    with connection.cursor() as cursor:
        cursor.execute('select count(*) from "Learner".learner_free_courses where free_course_ref=%s', [course_id])
        assignments = cursor.fetchone()[0]
        cursor.execute('select count(*) from "Learner".learner_free_course_progress where free_course_ref=%s', [course_id])
        progress = cursor.fetchone()[0]
        quiz_links = quizzes = 0
        if week_ids:
            cursor.execute('select count(*) from curriculum.quiz_course_links where free_course_id=%s or free_course_week_id=any(%s::varchar[])', [course_id, week_ids])
            quiz_links = cursor.fetchone()[0]
            cursor.execute('select count(*) from curriculum.quizzes where free_course_week_id=any(%s::varchar[])', [week_ids])
            quizzes = cursor.fetchone()[0]
        component_progress = 0
        if component_ids:
            cursor.execute('select count(*) from "Learner".learner_free_course_progress where component_ref=any(%s::varchar[])', [component_ids])
            component_progress = cursor.fetchone()[0]
    return {"assignments": assignments, "progress": progress, "componentProgress": component_progress,
            "quizLinks": quiz_links, "quizzes": quizzes}


def _changed(existing, values):
    for key, value in values.items():
        current = existing.get(key)
        if key in {"settings_json", "learning_outcomes"}:
            if documents.canonical_value(current) != documents.canonical_value(value):
                return True
        elif current != value:
            return True
    return False


def _update_row(cursor, table, ident, existing, values):
    if not _changed(existing, values):
        return False
    columns = [*values.keys(), "updated_at"]
    assignments = ",".join(f'"{column}"=%s' for column in columns)
    params = [json.dumps(value) if column in {"settings_json", "learning_outcomes"} else value
              for column, value in values.items()]
    params.extend([timezone.now(), ident])
    casts = assignments.replace('"settings_json"=%s', '"settings_json"=%s::jsonb').replace(
        '"learning_outcomes"=%s', '"learning_outcomes"=%s::jsonb')
    cursor.execute(f'update curriculum."{table}" set {casts} where id=%s', params)
    return True


def update_course(course_id, payload):
    if not isinstance(payload, dict):
        raise MutationError("validation_error", "Request body must be an object.")
    expected = _expected(payload)
    require_mode(CANONICAL)
    with transaction.atomic():
        _catalogue_lock()
        require_mode(CANONICAL)
        course, weeks, components = _tree(course_id, lock=True)
        current_document = documents.course_document(course_id, read_snapshot=False)
        _check_revision(expected, current_document["revision"], scope="course")
        if current_document["integrity"]["status"] == "blocked":
            raise MutationError("free_course_integrity_blocked", "Resolve blocking Free Course integrity issues before saving.", status=409,
                                issues=current_document["integrity"]["issues"])

        week_by_id = {row["id"]: row for row in weeks}
        component_by_id = {row["id"]: row for row in components}
        deleted_weeks = {_clean(value, maximum=128) for value in payload.get("deletedWeekIds", [])}
        deleted_components = {_clean(value, maximum=128) for value in payload.get("deletedComponentIds", [])}
        if not deleted_weeks.issubset(week_by_id):
            raise MutationError("cross_course_id", "A deleted week does not belong to this course.", status=409)
        if not deleted_components.issubset(component_by_id):
            raise MutationError("cross_course_id", "A deleted component does not belong to this course.", status=409)

        if deleted_weeks or deleted_components:
            # Archive content in place. Assignments, completions and quizzes keep
            # their original identities; a new component never inherits history.
            for week_id in deleted_weeks:
                remaining = [row["id"] for row in components if row["free_module_id"] == week_id and row["id"] not in deleted_components]
                if remaining:
                    raise MutationError("week_not_empty", "Delete or move no components before deleting a week.", status=409,
                                        freeCourseWeekId=week_id)

        raw_weeks = payload.get("weeks", [])
        if not isinstance(raw_weeks, list):
            raise MutationError("validation_error", "weeks must be a list.")
        if len(weeks) - len(deleted_weeks) + sum(1 for row in raw_weeks if not row.get("freeCourseWeekId")) > MAX_WEEKS:
            raise MutationError("limit_exceeded", "A course can contain at most 100 weeks.")
        seen_ids, seen_clients = set(), set()
        client_id_map = {"course": {}, "weeks": {}, "components": {}}
        now = timezone.now()
        with connection.cursor() as cursor:
            course_patch = payload.get("course") or {}
            if course_patch:
                merged = {
                    "courseName": course_patch.get("courseName", course["course_name"]),
                    "description": course_patch.get("description", course.get("description")),
                    "coverImageUrl": course_patch.get("coverImageUrl", course.get("cover_image_url")),
                    "courseType": course_patch.get("courseType", course.get("course_type")),
                    "isForSale": course_patch.get("isForSale", course.get("is_for_sale")),
                    "price": course_patch.get("price", course.get("price")),
                }
                values = _course_values(merged)
                values["cover_image_url"] = _stored_cover(course_id, values["cover_image_url"])
                _update_row(cursor, "free_courses", course_id, course, values)
                if "displayOrder" in course_patch:
                    catalogue_expected = _expected(payload, "expectedCatalogueRevision")
                    all_courses = _course_rows(lock=True)
                    _check_revision(catalogue_expected, _catalogue_revision(all_courses), scope="catalogue")
                    ordered = [row["id"] for row in all_courses if row["id"] != course_id]
                    target = min(_integer(course_patch["displayOrder"], minimum=0, label="displayOrder"), len(ordered))
                    ordered.insert(target, course_id)
                    for order, ident in enumerate(ordered):
                        cursor.execute("update curriculum.free_courses set display_order=%s,updated_at=case when display_order<>%s then %s else updated_at end where id=%s", [order, order, now, ident])

            for index, raw_week in enumerate(raw_weeks):
                week_id = _clean(raw_week.get("freeCourseWeekId"), maximum=128)
                if week_id:
                    if week_id in seen_ids:
                        raise MutationError("duplicate_id", "A week id appears more than once.")
                    seen_ids.add(week_id)
                    existing_week = week_by_id.get(week_id)
                    if not existing_week or week_id in deleted_weeks:
                        raise MutationError("cross_course_id", "A week does not belong to this course.", status=409)
                    week_values = _normalise_week(raw_week, index=index, existing=existing_week)
                    _update_row(cursor, "free_course_weeks", week_id, existing_week, week_values)
                else:
                    client_id = _client_id(raw_week.get("clientId"), seen_clients, "week clientId")
                    week_id = _new_id("FREEWEEK")
                    client_id_map["weeks"][client_id] = week_id
                    week_values = _normalise_week(raw_week, index=index)
                    cursor.execute(
                        "insert into curriculum.free_course_weeks (id,course_id,display_order,component_count,total_otjh,created_at,updated_at,week_number,title,summary,learning_outcomes,status,holiday_note_enabled,holiday_note,legacy_copied_from_week_id) values (%s,%s,%s,0,0,%s,%s,%s,%s,%s,%s::jsonb,%s,%s,%s,%s)",
                        [week_id, course_id, week_values["display_order"], now, now, week_values["week_number"], week_values["title"],
                         week_values["summary"], json.dumps(week_values["learning_outcomes"]), week_values["status"],
                         week_values["holiday_note_enabled"], week_values["holiday_note"], week_values["legacy_copied_from_week_id"]],
                    )

                raw_components = raw_week.get("components", [])
                if not isinstance(raw_components, list) or len(raw_components) > MAX_COMPONENTS_PER_WEEK:
                    raise MutationError("limit_exceeded", "A week can contain at most 100 components.")
                if week_values["status"] == "active" and not raw_components and not any(
                    row["free_module_id"] == week_id and row["id"] not in deleted_components for row in components
                ):
                    raise MutationError("active_week_empty", "Active weeks must contain at least one component.")
                for component_index, raw_component in enumerate(raw_components):
                    component_id = _clean(raw_component.get("id"), maximum=128)
                    if component_id:
                        if component_id in seen_ids:
                            raise MutationError("duplicate_id", "An id appears more than once.")
                        seen_ids.add(component_id)
                        existing_component = component_by_id.get(component_id)
                        if not existing_component or component_id in deleted_components:
                            raise MutationError("cross_course_id", "A component does not belong to this course.", status=409)
                        if existing_component["free_module_id"] != week_id:
                            raise MutationError("component_move_forbidden", "Existing components cannot move between Free Weeks.", status=409)
                        values = _normalise_component(raw_component, index=component_index, existing=existing_component)
                        _update_row(cursor, "free_programme_components", component_id, existing_component, values)
                    else:
                        client_id = _client_id(raw_component.get("clientId"), seen_clients, "component clientId")
                        component_id = _new_id("FREECOMP")
                        values = _normalise_component(raw_component, index=component_index)
                        cursor.execute(
                            "insert into curriculum.free_programme_components (id,free_module_id,programme_id,type,title,description,expected_otjh,points,reflection_required,workplace_evidence_required,tutor_validation_required,display_order,settings_json,created_at,updated_at) values (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb,%s,%s)",
                            [component_id, week_id, PROGRAMME_MARKER, values["type"], values["title"], values["description"], values["expected_otjh"], values["points"], values["reflection_required"], values["workplace_evidence_required"], values["tutor_validation_required"], values["display_order"], json.dumps(values["settings_json"]), now, now],
                        )
                        client_id_map["components"][client_id] = component_id

            if deleted_components:
                cursor.execute("update curriculum.free_programme_components set deleted_at=%s,updated_at=%s where id=any(%s::varchar[])", [now, now, list(deleted_components)])
            if deleted_weeks:
                cursor.execute("update curriculum.free_course_weeks set deleted_at=%s,updated_at=%s where id=any(%s::varchar[])", [now, now, list(deleted_weeks)])

            cursor.execute(
                "update curriculum.free_course_weeks w set component_count=s.c,total_otjh=s.h,updated_at=case when w.component_count<>s.c or w.total_otjh<>s.h then %s else w.updated_at end from (select w2.id,count(c.id)::int c,coalesce(sum(c.expected_otjh),0) h from curriculum.free_course_weeks w2 left join curriculum.free_programme_components c on c.free_module_id=w2.id and c.deleted_at is null where w2.course_id=%s and w2.deleted_at is null group by w2.id) s where w.id=s.id",
                [now, course_id],
            )
            cursor.execute(
                "update curriculum.free_courses c set week_count=s.w,component_count=s.n,total_otjh=s.h,updated_at=case when c.week_count<>s.w or c.component_count<>s.n or c.total_otjh<>s.h then %s else c.updated_at end from (select count(distinct w.id)::int w,count(p.id)::int n,coalesce(sum(p.expected_otjh),0) h from curriculum.free_course_weeks w left join curriculum.free_programme_components p on p.free_module_id=w.id and p.deleted_at is null where w.course_id=%s and w.deleted_at is null) s where c.id=%s",
                [now, course_id, course_id],
            )
            cursor.execute(
                "select count(distinct w.id)::int, count(p.id)::int, "
                "count(*) filter (where w.status='active' and exists (select 1 from curriculum.free_programme_components p2 where p2.free_module_id=w.id and p2.deleted_at is null))::int, "
                "count(*) filter (where w.status='active' and not exists (select 1 from curriculum.free_programme_components p3 where p3.free_module_id=w.id and p3.deleted_at is null))::int "
                "from curriculum.free_course_weeks w left join curriculum.free_programme_components p on p.free_module_id=w.id and p.deleted_at is null where w.course_id=%s and w.deleted_at is null",
                [course_id],
            )
            week_count, component_count, active_nonempty, active_empty = cursor.fetchone()
            if not week_count or not active_nonempty:
                raise MutationError("validation_error", "A course needs at least one active, non-empty week.")
            if active_empty:
                raise MutationError("active_week_empty", "Active weeks must contain at least one component.")
            if component_count > MAX_COMPONENTS:
                raise MutationError("limit_exceeded", "A course can contain at most 500 components.")
            cursor.execute(
                "select 1 from curriculum.free_course_weeks where course_id=%s and deleted_at is null group by display_order having count(*)>1 "
                "union all select 1 from curriculum.free_programme_components p join curriculum.free_course_weeks w on w.id=p.free_module_id "
                "where w.course_id=%s and w.deleted_at is null and p.deleted_at is null group by p.free_module_id,p.display_order having count(*)>1 limit 1",
                [course_id, course_id],
            )
            if cursor.fetchone():
                raise MutationError("duplicate_display_order", "Week and component displayOrder values must be unique.")

        result = documents.course_document(course_id, read_snapshot=False)
        result["clientIdMap"] = client_id_map
        from .free_course_videos import queue_saved_videos
        queue_saved_videos(course_id, components, result, payload.get('importVideoComponentIds', []))
        return result


def delete_course(course_id, payload):
    expected = _expected(payload if isinstance(payload, dict) else {})
    require_mode(CANONICAL)
    with transaction.atomic():
        _catalogue_lock()
        require_mode(CANONICAL)
        # Permanent course deletion must also protect history of archived content.
        _course, weeks, components = _tree(course_id, lock=True, include_deleted=True)
        current = documents.course_document(course_id, read_snapshot=False)
        _check_revision(expected, current["revision"], scope="course")
        counts = _dependency_counts(course_id, [row["id"] for row in weeks], [row["id"] for row in components])
        linked = []
        for row in components:
            settings, _issue = documents._decode_settings(row.get("settings_json") or {})
            if isinstance(settings, dict) and str(settings.get("linkedQuizId") or "").strip():
                linked.append(row["id"])
        if any(counts.values()) or linked:
            raise MutationError("dependent_records", "This Free Course has assignments, progress or quiz history and cannot be deleted.", status=409,
                                dependencies={**counts, "linkedComponents": linked})
        with connection.cursor() as cursor:
            cursor.execute("delete from curriculum.free_programme_components where free_module_id=any(%s::varchar[])", [[row["id"] for row in weeks]])
            cursor.execute("delete from curriculum.free_course_weeks where course_id=%s", [course_id])
            cursor.execute("delete from curriculum.free_courses where id=%s", [course_id])
        return {"deleted": True, "courseId": course_id, "catalogueRevision": _catalogue_revision()}


def clone_normal_module(payload, *, staff_id, idempotency_key):
    """Clone a normal Module into new canonical rows; never move its source."""
    if not isinstance(payload, dict):
        raise MutationError("validation_error", "Request body must be an object.")
    if str(payload.get("mode") or "clone").strip().lower() != "clone":
        raise MutationError("clone_only", "Normal Curriculum content can only be cloned into Free Courses.", status=409)
    module_id = _clean(payload.get("moduleCatalogueId"), maximum=128, required=True, label="moduleCatalogueId")
    from . import views as legacy_views

    structure = legacy_views.get_authoring_structure_payload(module_id)
    if not structure:
        raise MutationError("module_not_found", "Module not found.", status=404)
    weeks = []
    for week_index, week in enumerate(structure.get("weekStructure") or []):
        week_client = f"week:{week_index}:{week.get('id') or week_index}"
        components = []
        for component_index, component in enumerate(week.get("components") or []):
            settings = dict(component.get("settings") or {}) if isinstance(component.get("settings"), dict) else {}
            components.append({
                "clientId": f"component:{week_index}:{component_index}:{component.get('id') or component_index}",
                "type": component.get("type"),
                "title": component.get("title") or "Untitled activity",
                "description": component.get("description") or "",
                "expectedOtjh": component.get("expectedOtjh") or 0,
                "points": component.get("points") or 0,
                "reflectionRequired": bool(component.get("reflectionRequired")),
                "workplaceEvidenceRequired": bool(component.get("workplaceEvidenceRequired")),
                "tutorValidationRequired": bool(component.get("tutorValidationRequired")),
                "displayOrder": component_index,
                "settings": settings,
            })
        weeks.append({
            "clientId": week_client,
            "legacyCopiedFromWeekId": week.get("id") or None,
            "weekNumber": week.get("weekNumber") or week_index + 1,
            "title": week.get("title") or f"Week {week_index + 1}",
            "summary": week.get("summary") or "",
            "learningOutcomes": week.get("learningOutcomes") or [],
            "status": "active",
            "displayOrder": week_index,
            "components": components,
        })
    if not weeks:
        raise MutationError("module_empty", "The selected Module has no weeks to clone.", status=409)
    create_payload = {
        "expectedRevision": payload.get("expectedRevision"),
        "clientId": payload.get("clientId") or f"module:{module_id}",
        "course": {
            "courseName": structure.get("title") or "Untitled course",
            "description": structure.get("description") or "",
            "coverImageUrl": structure.get("coverImage") or "",
            "courseType": "free",
        },
        "weeks": weeks,
    }
    return create_course(
        create_payload,
        staff_id=staff_id,
        idempotency_key=idempotency_key,
    )

sources.free_course_alignment.py:
"""Insert-only alignment of architecture free courses with native storage.

No caller may use profile primary keys as cross-database identities. Existing
target rows win in full, including timestamps, order and archived history.
The enrolment JSON receives only newly imported assignments so normal plan
saves and the learner viewer retain them; training plans/hours are untouched.
"""
from collections import defaultdict
from copy import deepcopy
from dataclasses import dataclass
import hashlib
import json

from psycopg import sql
from psycopg.types.json import Jsonb

from .legacy_free_course_migration import adopted_id


TABLES = {
    'free_courses': 'curriculum',
    'free_course_weeks': 'curriculum',
    'free_programme_components': 'curriculum',
    'learner_free_courses': 'Learner',
    'learner_free_course_progress': 'Learner',
}


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, default=str,
                                     separators=(',', ':')).encode()).hexdigest()


def rows(database, query, params=()):
    with database.cursor() as cursor:
        cursor.execute(query, params)
        names = [column[0] for column in cursor.description]
        json_fields = {column[0] for column in cursor.description if column[1] in (114, 3802)}
        return [{name: json.loads(value) if name in json_fields and isinstance(value, str) else value
                 for name, value in zip(names, row)} for row in cursor.fetchall()]


def snapshot(database):
    data = {table: rows(database, sql.SQL('SELECT * FROM {} ORDER BY id').format(
        sql.Identifier(namespace, table))) for table, namespace in TABLES.items()}
    data['profiles'] = rows(database, 'SELECT id,enrolment_id FROM "Learner".learners ORDER BY id')
    data['assignments_json'] = rows(database, '''SELECT id,"Free_courses"::jsonb AS value
        FROM enrolment."Created_users" ORDER BY id''')
    data['enrolment_uuids'] = {r['id']: str(r['uuid']) for r in rows(database,
        'SELECT id,uuid FROM enrolment."Created_users" ORDER BY id')}
    data['quiz_ids'] = [row['id'] for row in rows(database, 'SELECT id FROM curriculum.quizzes ORDER BY id')]
    data['ordinary_refs'] = {table: [r['reference'] for r in rows(database,
        sql.SQL('SELECT {} AS reference FROM curriculum.{} ORDER BY {}').format(
            sql.Identifier(key), sql.Identifier(table), sql.Identifier(key)))]
        for table, key in (('modules', 'module_catalogue_id'), ('weeks', 'id'), ('components', 'id'))}
    return data


@dataclass
class Plan:
    inserts: dict
    assignment_appends: dict
    fingerprint: str
    unlinked_quizzes: int

    def summary(self):
        return {**{table: len(records) for table, records in self.inserts.items()},
                'assignment_json_records': sum(map(len, self.assignment_appends.values())),
                'unlinked_source_quizzes': self.unlinked_quizzes,
                'fingerprint': self.fingerprint}


def build_plan(source, target):
    inserts = {table: [] for table in TABLES}
    src = {table: {r['id']: r for r in source[table]} for table in TABLES}
    dst = {table: {r['id']: r for r in target[table]} for table in TABLES}
    new_courses = src['free_courses'].keys() - dst['free_courses'].keys()
    new_weeks = {key for key, week in src['free_course_weeks'].items() if week['course_id'] in new_courses}
    new_components = src['free_programme_components'].keys() - dst['free_programme_components'].keys()
    # A shared component proves the course identity even when old week IDs
    # were renamed during production's native-storage migration.
    for key, component in src['free_programme_components'].items():
        source_course = src['free_course_weeks'][component['free_module_id']]['course_id']
        if key in dst['free_programme_components']:
            old = dst['free_programme_components'][key]
            if dst['free_course_weeks'][old['free_module_id']]['course_id'] != source_course:
                raise ValueError('A shared component has conflicting course ownership.')
        elif source_course not in new_courses:
            raise ValueError('New content in an existing course needs explicit reconciliation.')
    if new_weeks & dst['free_course_weeks'].keys():
        raise ValueError('A new course reuses an existing week identity.')
    for key in sorted(new_courses):
        original = src['free_courses'][key]
        reference = adopted_id('MOD', key, key)
        data = dict(original)
        data.update(content_ref=reference, managed_by_builder=True, storage_version=2,
                    authoring_data={
                        'module_catalogue_id': reference, 'title': original['course_name'],
                        'description': original.get('description'), 'source_type': 'free_course',
                        'source_id': key, 'learner_roster_mode': 'manual',
                        'is_programme_deleted': False, 'session_overrides': {},
                        'sessions_number': 0, 'quality_score': 0,
                    })
        inserts['free_courses'].append(data)
    for key in sorted(new_weeks):
        original = src['free_course_weeks'][key]
        if original.get('status', 'active') != 'active':
            raise ValueError('Importing inactive weeks requires an explicit archive-state mapping.')
        owner = src['free_courses'][original['course_id']]
        reference = adopted_id('WEEK', owner['id'], key)
        data = {field: original[field] for field in (
            'id', 'course_id', 'week_number', 'display_order', 'created_at', 'updated_at')}
        data.update({field: original[field] for field in ('component_count', 'total_otjh') if field in original})
        data.update(week_title=original['title'], course_name=owner['course_name'],
                    week_id=reference, content_ref=reference,
                    authoring_data={**original, 'id': reference,
                        'module_catalogue_id': adopted_id('MOD', owner['id'], owner['id']),
                        'is_programme_deleted': False, 'library_state': ''})
        inserts['free_course_weeks'].append(data)
    unlinked = 0
    for key in sorted(new_components):
        original = src['free_programme_components'][key]
        week = src['free_course_weeks'][original['free_module_id']]
        owner = week['course_id']
        reference = adopted_id('COMP', owner, key)
        settings = original.get('settings_json') or {}
        if not isinstance(settings, dict):
            raise ValueError('Component settings must be a JSON object.')
        if original['type'] == 'quiz':
            linked = settings.get('linkedQuizId')
            if linked and int(linked) not in target['quiz_ids']:
                raise ValueError('An imported quiz definition is missing from the target.')
            unlinked += not bool(linked)
        data = dict(original)
        data.update(content_ref=reference, week_id=adopted_id('WEEK', owner, week['id']),
                    authoring_data={**original, 'id': reference,
                        'module_catalogue_id': adopted_id('MOD', owner, owner),
                        'week_id': adopted_id('WEEK', owner, week['id']),
                        'is_programme_deleted': False, 'library_state': '', 'ksb_mappings': []})
        inserts['free_programme_components'].append(data)
    for ordinary, native in (('modules','free_courses'), ('weeks','free_course_weeks'),
                             ('components','free_programme_components')):
        if {r['content_ref'] for r in inserts[native]} & set(target['ordinary_refs'][ordinary]):
            raise ValueError('An imported native identity is already owned by ordinary curriculum content.')
    source_profiles = {r['id']: r['enrolment_id'] for r in source['profiles']}
    target_profiles = defaultdict(list)
    for profile in target['profiles']:
        if profile['enrolment_id'] is not None:
            target_profiles[profile['enrolment_id']].append(profile['id'])

    def learner(source_id):
        enrolment = source_profiles.get(source_id)
        matches = target_profiles.get(enrolment, [])
        if enrolment is None or len(matches) != 1:
            raise ValueError('A learner cannot be matched unambiguously by enrolment identity.')
        source_uuid = source['enrolment_uuids'].get(enrolment)
        if not source_uuid or source_uuid != target['enrolment_uuids'].get(enrolment):
            raise ValueError('The enrolment UUID differs between branches; learner identity is not verified.')
        return matches[0], enrolment

    known = {(r['learner_id'], r['free_course_ref']) for r in target['learner_free_courses']}
    positions = defaultdict(int)
    for record in target['learner_free_courses']:
        positions[record['learner_id']] = max(positions[record['learner_id']], record['position'])
    legacy = {r['id']: r['value'] for r in target['assignments_json']}
    appends = defaultdict(list)
    for record in sorted(source['learner_free_courses'], key=lambda r: (r['learner_id'], r['position'], r['id'])):
        target_id, enrolment = learner(record['learner_id'])
        course_id = record['free_course_ref']
        if course_id not in src['free_courses']:
            raise ValueError('A source assignment has no course.')
        if (target_id, course_id) in known:
            continue
        positions[target_id] += 1
        course = dst['free_courses'].get(course_id, src['free_courses'][course_id])
        if course.get('converted_at') or course.get('deleted_at'):
            raise ValueError('An imported assignment targets a converted or archived production course.')
        inserts['learner_free_courses'].append(dict(learner_id=target_id, free_course_ref=course_id,
            position=positions[target_id], free_course_title=course['course_name']))
        known.add((target_id, course_id))
        if enrolment not in legacy or not isinstance(legacy[enrolment], list):
            raise ValueError('The target enrolment assignment store is missing or not a list.')
        if not any(isinstance(item, dict) and item.get('freeCourseId') == course_id for item in legacy[enrolment]):
            appends[enrolment].append(dict(freeCourseId=course_id, courseName=course['course_name'], addedAt=''))
    known = {(r['learner_id'], r['component_ref']) for r in target['learner_free_course_progress']}
    for record in source['learner_free_course_progress']:
        target_id, _ = learner(record['learner_id'])
        if (target_id, record['component_ref']) in known:
            continue
        component = src['free_programme_components'].get(record['component_ref'])
        if not component or src['free_course_weeks'][component['free_module_id']]['course_id'] != record['free_course_ref']:
            raise ValueError('Source progress has conflicting course/component ownership.')
        if record['status'] not in ('active', 'inactive'):
            raise ValueError('Unknown source progress state.')
        if (record['activity_state'] not in ('not_started', 'reading_viewed', 'completed')
                or record['is_completed'] != (record['activity_state'] == 'completed')):
            raise ValueError('Conflicting source activity completion state.')
        inserts['learner_free_course_progress'].append({**{k: record[k] for k in
            ('free_course_ref', 'component_ref', 'completed_at', 'status', 'deleted_at',
             'is_completed', 'activity_state')}, 'learner_id': target_id})
        known.add((target_id, record['component_ref']))
    return Plan(inserts, dict(appends), digest([source, target]), unlinked)


def apply_plan(database, plan, before):
    """Caller owns the transaction and locks; every original row is verified."""
    def original_state():
        return {table: rows(database, sql.SQL('''SELECT count(*) AS count,
            md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY id),'')) AS checksum
            FROM {} t WHERE id=ANY(%s)''').format(sql.Identifier(namespace, table)),
            [[r['id'] for r in before[table]]])[0] for table,namespace in TABLES.items()}

    original = original_state()
    affected = list(plan.assignment_appends)
    def enrolment_state():
        return rows(database, '''SELECT id,md5((to_jsonb(u)-'Free_courses')::text) AS other_fields,
            "Free_courses"::jsonb AS value FROM enrolment."Created_users" u
            WHERE id=ANY(%s) ORDER BY id''', [affected])

    enrolments_before = enrolment_state()
    with database.cursor() as cursor:
        for table, records in plan.inserts.items():
            grouped = defaultdict(list)
            for record in records:
                grouped[tuple(record)].append(record)
            for fields, batch in grouped.items():
                cursor.executemany(sql.SQL('INSERT INTO {} ({}) VALUES ({})').format(
                    sql.Identifier(TABLES[table], table), sql.SQL(',').join(map(sql.Identifier, fields)),
                    sql.SQL(',').join(sql.Placeholder() for _ in fields)),
                    [[Jsonb(json.loads(json.dumps(record[k], default=str)))
                      if isinstance(record[k], (dict, list)) else record[k] for k in fields] for record in batch])
                if cursor.rowcount != len(batch):
                    raise ValueError('Unexpected inserted row count; alignment rolled back.')
        if affected:
            cursor.executemany('''UPDATE enrolment."Created_users"
                SET "Free_courses"=("Free_courses"::jsonb || %s::jsonb) WHERE id=%s''',
                [[Jsonb(additions), enrolment] for enrolment,additions in plan.assignment_appends.items()])
            if cursor.rowcount != len(affected):
                raise ValueError('An enrolment assignment update missed its expected rows.')
    if original != original_state():
        raise ValueError('An existing target row changed; alignment rolled back.')
    for table in TABLES:
        count = rows(database, sql.SQL('SELECT count(*) AS count FROM {}').format(
            sql.Identifier(TABLES[table], table)))[0]['count']
        if count != len(before[table]) + len(plan.inserts[table]):
            raise ValueError('Unexpected inserted row count; alignment rolled back.')
    expected = deepcopy(enrolments_before)
    for row in expected:
        if row['id'] in plan.assignment_appends:
            row['value'] += plan.assignment_appends[row['id']]
    if expected != enrolment_state():
        raise ValueError('Existing learner assignment/identity values changed; alignment rolled back.')

sources.free_course_catalogue_store.py:
"""Free-course catalogue save for the self-contained schema (the new database).

On the new database a free course is three tables of its own::

    curriculum.free_courses.id
      -> curriculum.free_course_weeks.course_id          (ON DELETE RESTRICT)
         -> curriculum.free_programme_components.free_module_id   (RESTRICT)

and learner records point into them: ``Learner.learner_free_courses`` at the
course, ``Learner.learner_free_course_progress`` at the course and the
component (both RESTRICT). A week stores its own title, summary, learning
outcomes and status; there is no ``curriculum.weeks`` mirror any more.

The legacy save (``views.save_free_programme_modules``) deleted every row and
inserted it again, and mirrored each week into ``curriculum.weeks``. Here that
cannot work -- the mirror write breaks the weeks->modules key, and the delete is
refused as soon as one learner holds an assignment or a completion -- so this
save compares the incoming catalogue with what is stored and:

* keeps every stored id (course, week and component) the client sends back;
* writes only the rows that changed, one batched statement per table;
* deletes only what was removed, and refuses (FreeCourseInUse) to remove a
  course that learners are assigned to, or an activity a learner completed;
* leaves archived (inactive) weeks and their activities alone -- the catalogue
  does not show them, so their absence from a save is not a removal.
"""
import hashlib
import json
import re
from datetime import datetime
from decimal import Decimal

from django.db import connection, transaction

from . import schema_compat
from .course_pricing import pricing_values

COURSE_ID = re.compile(r'^FREECOURSE-[A-Za-z0-9][A-Za-z0-9_-]*$')
WEEK_ID = re.compile(r'^(?:FREEWEEK|FREEWLINK)-[A-Za-z0-9][A-Za-z0-9_-]*$')
JSON_COLUMNS = frozenset({'settings_json', 'learning_outcomes'})
BATCH_ROWS = 200

# is_for_sale / price / currency: a free course's sale metadata lives on its
# own row (free_course_pricing); the catalogue save keeps or sets it per course.
COURSE_COLUMNS = ('id', 'course_name', 'description', 'cover_image_url', 'display_order',
                  'week_count', 'component_count', 'total_otjh', 'is_for_sale', 'price', 'currency')
WEEK_COLUMNS = ('id', 'course_id', 'week_number', 'title', 'summary', 'learning_outcomes', 'status',
                'holiday_note_enabled', 'display_order', 'component_count', 'total_otjh')
COMPONENT_COLUMNS = ('id', 'free_module_id', 'programme_id', 'type', 'title', 'description', 'expected_otjh',
                     'points', 'reflection_required', 'workplace_evidence_required',
                     'tutor_validation_required', 'display_order', 'settings_json')


class FreeCourseInUse(ValueError):
    """A removal the learner records refuse. Nothing has been written."""


def applies():
    """True on the self-contained free-course schema (see module docstring)."""
    from . import views
    if connection.vendor != 'postgresql':
        return False
    return schema_compat.free_weeks_self_contained(views.column_names(views.FREE_PROGRAMME_MODULES_TABLE))


def _views():
    from . import views
    return views


def _quote(name):
    return '"' + name.replace('"', '""') + '"'


def _comparable(value):
    """Normalise a stored or incoming value so equal content compares equal."""
    if isinstance(value, Decimal):
        return float(value)
    if isinstance(value, str):
        stripped = value.strip()
        if stripped[:1] in ('{', '['):
            try:
                return json.loads(stripped)
            except ValueError:
                return value
    return value


def _same(new, old):
    if new in (None, '') and old in (None, ''):
        return True  # an empty text column reads back as NULL or ''
    return _comparable(new) == _comparable(old)


def _jsonb_text(value):
    """``value`` as PostgreSQL prints jsonb: keys by length then bytes, ', ' and ': '."""
    if isinstance(value, dict):
        items = sorted(value.items(), key=lambda item: (len(item[0].encode('utf-8')), item[0].encode('utf-8')))
        return '{' + ', '.join(json.dumps(key, ensure_ascii=False) + ': ' + _jsonb_text(item)
                               for key, item in items) + '}'
    if isinstance(value, list):
        return '[' + ', '.join(_jsonb_text(item) for item in value) + ']'
    return json.dumps(value, ensure_ascii=False)


def _jsonb_md5(value):
    """md5(column::text) for the JSON ``value`` would hold once stored.

    A mismatch only ever costs a write of identical content (a number printed
    differently, say), never a missed change: equal hashes mean equal text.
    """
    return hashlib.md5(_jsonb_text(_comparable(value)).encode('utf-8')).hexdigest()


def _changed(new_row, old_row):
    if old_row is None:
        return True
    for key, value in new_row.items():
        if key == 'settings_json' and 'settings_md5' in old_row:
            if _jsonb_md5(value) != old_row['settings_md5']:
                return True
        elif not _same(value, old_row.get(key)):
            return True
    return False


def _bulk_upsert(table, rows, columns):
    """Insert-or-update ``rows`` in batches of one statement each.

    ``created_at`` is set only on insert; ``updated_at`` on every write.
    Columns the table does not have are dropped.
    """
    if not rows:
        return
    views = _views()
    present = set(views.column_names(table))
    names = [column for column in columns if column in present]
    stamp = datetime.utcnow()
    insert_names = [*names, 'updated_at', 'created_at']
    row_sql = '(' + ', '.join(
        '%s::jsonb' if name in JSON_COLUMNS else '%s' for name in insert_names
    ) + ')'
    updates = ', '.join(f'{_quote(name)} = excluded.{_quote(name)}' for name in [*names, 'updated_at'] if name != 'id')
    target = views.authoring_table_name(table)
    for start in range(0, len(rows), BATCH_ROWS):
        batch = rows[start:start + BATCH_ROWS]
        params = []
        for row in batch:
            params.extend([row.get(name) for name in names])
            params.extend([stamp, stamp])
        sql = (
            f'insert into {target} ({", ".join(_quote(name) for name in insert_names)}) '
            f'values {", ".join([row_sql] * len(batch))} '
            f'on conflict ("id") do update set {updates}'
        )
        with connection.cursor() as cursor:
            cursor.execute(sql, params)


def _delete_ids(table, column, ids):
    if not ids:
        return
    with connection.cursor() as cursor:
        cursor.execute(
            f'delete from {_views().authoring_table_name(table)} where {_quote(column)} = any(%s)',
            [list(ids)],
        )


def _rows(sql, params):
    with connection.cursor() as cursor:
        cursor.execute(sql, params)
        columns = [column.name for column in cursor.description]
        return [dict(zip(columns, row)) for row in cursor.fetchall()]


def _rows_many(queries):
    """Parameterless SELECTs sent as one multi-statement query; one row list each."""
    results = []
    with connection.cursor() as cursor:
        cursor.execute('; '.join(queries))
        while True:
            columns = [column.name for column in cursor.description]
            results.append([dict(zip(columns, row)) for row in cursor.fetchall()])
            if not cursor.nextset():
                break
    if len(results) != len(queries):
        raise RuntimeError(f'Expected {len(queries)} result sets, got {len(results)}.')
    return results


def _plural(count, word, plural=None):
    return f'{count} {word if count == 1 else (plural or word + "s")}'


def refuse_in_use(course_ids=(), component_ids=(), course_names=None, component_titles=None):
    """Raise FreeCourseInUse when learner records still point at these rows."""
    course_ids = sorted({value for value in course_ids if value})
    component_ids = sorted({value for value in component_ids if value})
    course_names = course_names or {}
    component_titles = component_titles or {}
    problems = []
    if course_ids:
        for row in _rows(
            'select free_course_ref as id, count(distinct learner_id) as learners '
            'from "Learner"."learner_free_courses" where free_course_ref = any(%s) group by 1 order by 1',
            [course_ids],
        ):
            name = course_names.get(row['id']) or row['id']
            problems.append(f'"{name}" is assigned to {_plural(row["learners"], "learner")}; '
                            'remove it from their learning plans first.')
    progress_sql = (
        'select {key} as id, count(distinct learner_id) as learners '
        'from "Learner"."learner_free_course_progress" where {key} = any(%s) group by 1 order by 1'
    )
    if course_ids:
        for row in _rows(progress_sql.format(key='free_course_ref'), [course_ids]):
            name = course_names.get(row['id']) or row['id']
            problems.append(f'"{name}" has completed activities from {_plural(row["learners"], "learner")}, '
                            'and their completion history cannot be deleted.')
    if component_ids:
        completed = _rows(progress_sql.format(key='component_ref'), [component_ids])
        if completed:
            titles = [f'"{component_titles.get(row["id"]) or row["id"]}"' for row in completed[:5]]
            more = f' and {len(completed) - 5} more' if len(completed) > 5 else ''
            problems.append(f'{_plural(len(completed), "activity", "activities")} that learners have completed cannot be '
                            f'removed: {", ".join(titles)}{more}. Keep them in the course.')
    if problems:
        raise FreeCourseInUse('This change was not saved. ' + ' '.join(problems))


def _resolve_week_id(module, course_id, stored_weeks, used):
    """Keep the stored week this entry names, else a well-formed requested id, else mint."""
    views = _views()
    candidates = [views.clean_str(module.get(key)) for key in ('id', 'moduleId', 'weekId', 'week_id')]
    for candidate in candidates:
        stored = stored_weeks.get(candidate)
        if candidate and candidate not in used and stored and stored.get('course_id') == course_id:
            return candidate
    requested = candidates[0] or candidates[1]
    if requested and WEEK_ID.match(requested) and requested not in used and requested not in stored_weeks:
        return requested
    return views.unique_timestamp_prefixed_id('FREEWEEK', [*stored_weeks, *used])


def _keep_stored_order(courses, weeks, stored_courses, stored_weeks):
    """Keep stored order and archived-week totals so an unchanged save writes nothing.

    * A stored course keeps its display_order; a new one goes after the rest.
    * A course's weeks keep their stored display_order while the client sends
      them in the stored sequence; once it reorders, adds or drops a week, that
      course's weeks are renumbered 0..n-1 (the order the client sent).
    * Archived weeks are not sent, but the stored course totals count them, so
      they are added back.
    """
    next_order = max((row.get('display_order') or 0 for row in stored_courses.values()), default=-1) + 1
    for course_id, course in courses.items():
        if course_id in stored_courses:
            course['display_order'] = stored_courses[course_id].get('display_order') or 0
        else:
            course['display_order'] = next_order
            next_order += 1

    by_course = {}
    for week in weeks:
        by_course.setdefault(week['course_id'], []).append(week)
    for course_id, course_weeks in by_course.items():
        live = sorted(
            (row for row in stored_weeks.values()
             if row.get('course_id') == course_id and not schema_compat.status_is_inactive(row.get('status'))),
            key=lambda row: (row.get('display_order') or 0, row.get('week_number') or 0, row['id']),
        )
        unchanged = [row['id'] for row in live] == [week['id'] for week in course_weeks]
        for index, week in enumerate(course_weeks):
            week['display_order'] = stored_weeks[week['id']].get('display_order') or 0 if unchanged else index

    for week in stored_weeks.values():
        course = courses.get(week.get('course_id'))
        if course and schema_compat.status_is_inactive(week.get('status')):
            course['week_count'] += 1
            course['component_count'] += week.get('component_count') or 0
            course['total_otjh'] = round(course['total_otjh'] + float(week.get('total_otjh') or 0), 2)


def save_catalogue(programme_id, modules):
    """Save the whole free-course catalogue the client sent (see module docstring)."""
    with transaction.atomic():
        _save_catalogue(programme_id, modules)


def _save_catalogue(programme_id, modules):
    views = _views()
    programme_id = views.clean_str(programme_id)

    # The stored catalogue, read in one round trip (three result sets).
    course_rows, week_rows, component_rows = _rows_many([
        f'select {", ".join(COURSE_COLUMNS)} from {views.authoring_table_name(views.FREE_COURSES_TABLE)}',
        f'select {", ".join(WEEK_COLUMNS)} from {views.authoring_table_name(views.FREE_PROGRAMME_MODULES_TABLE)}',
        # settings_json is most of the catalogue's bytes (reading text): the
        # snapshot takes its hash, which is all the change check needs.
        f'select {", ".join(column for column in COMPONENT_COLUMNS if column != "settings_json")}, '
        f'md5(settings_json::text) as settings_md5 '
        f'from {views.authoring_table_name(views.FREE_PROGRAMME_COMPONENTS_TABLE)}',
    ])
    stored_courses = {row['id']: row for row in course_rows}
    stored_weeks = {row['id']: row for row in week_rows}
    stored_components = {row['id']: row for row in component_rows}

    courses, weeks, components = {}, [], []
    course_ids_by_key = {}
    used_week_ids, used_component_ids = set(), set()
    stored_cover_urls = {}
    for module_index, module in enumerate(modules):
        if not isinstance(module, dict):
            continue
        course_name = views.clean_str(module.get('courseName') or module.get('course_name')
                                      or module.get('title') or module.get('name'))
        description = views.clean_str(module.get('description') or '')
        raw_cover = views.clean_str(module.get('coverImageUrl') or module.get('cover_image_url') or '')
        requested_course = views.clean_str(module.get('courseId') or module.get('course_id'))
        if requested_course and (requested_course in stored_courses or COURSE_ID.match(requested_course)):
            course_id = requested_course
        else:
            key = (course_name, description, raw_cover)
            if key not in course_ids_by_key:
                course_ids_by_key[key] = views.unique_timestamp_prefixed_id(
                    'FREECOURSE', [*stored_courses, *courses, *course_ids_by_key.values()])
            course_id = course_ids_by_key[key]

        if course_id not in courses:
            cover_key = (course_id, raw_cover)
            if cover_key not in stored_cover_urls:
                stored_cover_urls[cover_key] = views.stored_module_cover_image(course_id, raw_cover)
            # Omitted sale values keep the stored ones (course_pricing.pricing_values).
            try:
                sale = pricing_values(module, stored_courses.get(course_id) or {})
            except ValueError as error:
                raise ValueError(f'{course_name or "Free course"}: {error.args[1]}') from error
            courses[course_id] = {
                'id': course_id,
                'course_name': course_name or f'Free course {len(courses) + 1}',
                'description': description,
                'cover_image_url': stored_cover_urls[cover_key],
                'display_order': len(courses),
                'week_count': 0,
                'component_count': 0,
                'total_otjh': 0.0,
                **sale,
            }
        course = courses[course_id]

        week_id = _resolve_week_id(module, course_id, stored_weeks, used_week_ids)
        used_week_ids.add(week_id)
        stored_week = stored_weeks.get(week_id) or {}
        structure = module.get('weekStructure') if isinstance(module.get('weekStructure'), list) else module.get('weeks')
        week_input = next((item for item in structure if isinstance(item, dict)), {}) if isinstance(structure, list) else {}
        week_number = max(1, views.parse_int(module.get('weekNumber') or module.get('week_number')
                                             or week_input.get('weekNumber'), module_index + 1))
        week_title = views.clean_str(module.get('weekTitle') or module.get('week_title') or week_input.get('title')
                                     or stored_week.get('title') or course['course_name'] or f'Week {week_number}')
        # The catalogue screen sends no per-week summary or outcomes: keep the
        # stored ones unless this entry carries its own.
        summary = week_input.get('summary') if 'summary' in week_input else stored_week.get('summary')
        outcomes = week_input.get('learningOutcomes', week_input.get('learning_outcomes'))
        if outcomes is None:
            outcomes = _comparable(stored_week.get('learning_outcomes')) or []

        week_components = views.active_components_payload(
            module.get('components') if isinstance(module.get('components'), list) else [])
        minutes = 0
        for component_index, component in enumerate(week_components):
            payload = views.free_programme_component_payload(component, component_index)
            if not payload:
                continue
            if payload['id'] in used_component_ids:
                payload['id'] = views.canonical_authoring_id('FREECOMP')
            used_component_ids.add(payload['id'])
            minutes += views.component_expected_otjh_minutes(component)
            components.append({**payload, 'free_module_id': week_id, 'programme_id': programme_id})
        total_otjh = round(float(views.otjh_hours_from_minutes(minutes) or 0), 2)
        component_count = sum(1 for row in components if row['free_module_id'] == week_id)

        weeks.append({
            'id': week_id,
            'course_id': course_id,
            'week_number': week_number,
            'title': week_title,
            'summary': summary,
            'learning_outcomes': json.dumps(outcomes if isinstance(outcomes, list) else []),
            'status': stored_week.get('status') or schema_compat.ACTIVE,
            'holiday_note_enabled': bool(stored_week.get('holiday_note_enabled')),
            'display_order': module_index,
            'component_count': component_count,
            'total_otjh': total_otjh,
        })
        course['week_count'] += 1
        course['component_count'] += component_count
        course['total_otjh'] = round(course['total_otjh'] + total_otjh, 2)

    _keep_stored_order(courses, weeks, stored_courses, stored_weeks)

    # Owned = this programme's stored rows. A course is this programme's when
    # none of its activities belong to another programme.
    foreign_weeks = {row['free_module_id'] for row in stored_components.values()
                     if row.get('programme_id') != programme_id}
    foreign_courses = {stored_weeks[week]['course_id'] for week in foreign_weeks if week in stored_weeks}
    removed_courses = {course for course in stored_courses if course not in courses and course not in foreign_courses}
    incoming_weeks = {row['id'] for row in weeks}
    archived = {week for week, row in stored_weeks.items() if schema_compat.status_is_inactive(row.get('status'))}
    removed_weeks = {
        week for week, row in stored_weeks.items()
        if week not in incoming_weeks and week not in foreign_weeks
        and (row.get('course_id') in removed_courses or week not in archived)
    }
    incoming_components = {row['id'] for row in components}
    removed_components = {
        component for component, row in stored_components.items()
        if row.get('programme_id') == programme_id and component not in incoming_components
        and (row.get('free_module_id') in removed_weeks or row.get('free_module_id') not in archived)
    }
    refuse_in_use(
        removed_courses,
        # An activity of a refused course is already reported with its course.
        [component for component in removed_components
         if stored_weeks.get(stored_components[component].get('free_module_id'), {}).get('course_id')
         not in removed_courses],
        course_names={key: row.get('course_name') for key, row in stored_courses.items()},
        component_titles={key: row.get('title') for key, row in stored_components.items()},
    )

    # Parents before children on write, children before parents on delete: a
    # moved activity lands on its new week before its old week goes.
    _bulk_upsert(views.FREE_COURSES_TABLE,
                 [row for row in courses.values() if _changed(row, stored_courses.get(row['id']))], COURSE_COLUMNS)
    _bulk_upsert(views.FREE_PROGRAMME_MODULES_TABLE,
                 [row for row in weeks if _changed(row, stored_weeks.get(row['id']))], WEEK_COLUMNS)
    _bulk_upsert(views.FREE_PROGRAMME_COMPONENTS_TABLE,
                 [row for row in components if _changed(row, stored_components.get(row['id']))], COMPONENT_COLUMNS)
    _delete_ids(views.FREE_PROGRAMME_COMPONENTS_TABLE, 'id', removed_components)
    _delete_ids(views.FREE_PROGRAMME_MODULES_TABLE, 'id', removed_weeks)
    _delete_ids(views.FREE_COURSES_TABLE, 'id', removed_courses)


def delete_course(course_id):
    """Delete one free course (the "move" conversion) on the self-contained schema.

    The caller has already removed the learner assignments the move scrubs.
    Completion history is never deleted, so a course learners completed
    activities in is refused -- copy it instead.
    """
    views = _views()
    course = _rows(f'select id, course_name from {views.authoring_table_name(views.FREE_COURSES_TABLE)} '
                   'where id = %s', [course_id])
    refuse_in_use([course_id], course_names={course_id: course[0]['course_name']} if course else None)
    weeks = [row['id'] for row in _rows(
        f'select id from {views.authoring_table_name(views.FREE_PROGRAMME_MODULES_TABLE)} where course_id = %s',
        [course_id])]
    _delete_ids(views.FREE_PROGRAMME_COMPONENTS_TABLE, 'free_module_id', weeks)
    _delete_ids(views.FREE_PROGRAMME_MODULES_TABLE, 'id', weeks)
    _delete_ids(views.FREE_COURSES_TABLE, 'id', [course_id])

sources.free_course_policy.py:
"""Standalone courses use the ordinary module/content/progress stores.

The source marker distinguishes newly authored courses from unplaced modules
and ordinary modules. Adopted legacy courses retain their existing live content.
"""

FREE_COURSE_SOURCE = 'free_course'
UNASSIGNED = {'', 'unassigned', 'unassigned programme'}


def retained_live_component_ids(stored):
    """Only already stored live components of an adopted course are allowed."""
    from .legacy_free_course_migration import adopted_id
    source_id = (stored or {}).get('source_id')
    if (not source_id or stored.get('source_type') != FREE_COURSE_SOURCE
            or stored.get('module_catalogue_id') != adopted_id('MOD', source_id, source_id)):
        return set()
    from curriculum_api.catalogue.infrastructure.authoring_runtime import authoring_fetch_all
    from curriculum_api.catalogue.infrastructure.database_reads import AUTHORING_COMPONENTS_TABLE
    return {row['id'] for row in authoring_fetch_all(
        AUTHORING_COMPONENTS_TABLE,
        "module_catalogue_id = %s and type = 'live_session' and lower(btrim(coalesce(status, ''))) <> 'inactive'",
        [stored['module_catalogue_id']], columns=['id'],
    )}


def free_course_errors(payload, stored=None, *, allowed_live_ids=None):
    stored = stored or {}
    if stored and stored.get('source_type') != FREE_COURSE_SOURCE:
        return [{'path': 'isFreeCourse', 'message': 'Create a new free course; existing modules cannot be converted by editing their type.'}]
    errors = []
    if stored.get('source_id'):
        for key in ('sourceId', 'source_id'):
            if key in payload and payload[key] not in (None, '', stored['source_id']):
                errors.append({'path': key, 'message': 'The free course source identity cannot be changed.'})
    allowed_live_ids = retained_live_component_ids(stored) if allowed_live_ids is None else set(allowed_live_ids)
    metadata = payload.get('deliveryMetadata') if isinstance(payload.get('deliveryMetadata'), dict) else {}
    for key in ('programmeId', 'programme_id', 'programme', 'programmeName', 'programme_name',
                'cohortId', 'cohort_id', 'cohort', 'cohortName', 'cohort_name',
                'groupId', 'group_id', 'group', 'groupName', 'group_name'):
        for values in (payload, metadata):
            value = str(values.get(key) or '').strip().lower()
            if value not in UNASSIGNED:
                errors.append({'path': key, 'message': 'Free courses are independent of programmes, cohorts and groups.'})
    for key in ('teamsSharedSourceModuleId', 'teams_shared_source_module_id', 'weeklySchedule',
                'weekDays', 'startTime', 'endTime', 'teamsLiveSessionId', 'teamsJoinUrl',
                'teamsMeetingUrl', 'teamsEventId'):
        if payload.get(key) or metadata.get(key):
            errors.append({'path': key, 'message': 'Free courses contain self-study content only; Teams and delivery schedules are unavailable.'})
    weeks = payload.get('weekStructure') if 'weekStructure' in payload else payload.get('weeks', [])
    for wi, week in enumerate(weeks if isinstance(weeks, list) else []):
        for ci, component in enumerate(week.get('components') or []):
            if (str(component.get('type') or '').lower().replace('_', '-').replace(' ', '-') == 'live-session'
                    and component.get('id') not in allowed_live_ids):
                errors.append({'path': f'weekStructure[{wi}].components[{ci}].type',
                               'message': 'Live sessions are unavailable in a self-study free course.'})
    return errors
